// library.js — fixture profiles the studio can patch.
//  Wincode profiles are data (fixtures/wincode.json, generated by tools/import-wincode.mjs); generic profiles are built here.
//  A profile: { id, manufacturer, model, short, defaultMode, modes: { id: { label, channels: [channel] } }, sim? }
//  A channel: { key, name, base, head, grp, def, fine?, fineOf?, ranges: [[from, to, label]] }
//   grp: I intensity · P position · C colour · B beam · X control. Intensity channels merge HTP and follow the grand master.
import { store } from './store.js';
import { profileFromDesc } from './libimport.js';

export const GROUPS = { I: 'Intensity', P: 'Position', C: 'Colour', B: 'Beam', X: 'Control' };
const DEFS = new Map();
const NAMES = { dimmer: 'Dimmer', r: 'Red', g: 'Green', b: 'Blue', w: 'White', a: 'Amber', uv: 'UV', pan: 'Pan', panFine: 'Pan Fine', tilt: 'Tilt', tiltFine: 'Tilt Fine', strobe: 'Shutter',
  color: 'Colour', gobo: 'Gobo', prism: 'Prism', zoom: 'Zoom', focus: 'Focus', ptSpeed: 'P/T Speed', cyan: 'Cyan', magenta: 'Magenta', yellow: 'Yellow' };
const GRP = { dimmer: 'I', pan: 'P', panFine: 'P', tilt: 'P', tiltFine: 'P', ptSpeed: 'P', r: 'C', g: 'C', b: 'C', w: 'C', a: 'C', uv: 'C', color: 'C', cyan: 'C', magenta: 'C', yellow: 'C' };
const ch = (key, name) => { const m = /^([a-zA-Z]+?)(\d*)$/.exec(key), base = m[1], head = +m[2] || 0;
  return { key, name: name || NAMES[base] || key, base, head, grp: GRP[base] || 'B', def: base === 'pan' || base === 'tilt' ? 128 : base === 'strobe' ? 255 : 0, ranges: [] }; };
function generic(id, model, modes) {
  const out = { id: 'generic/' + id, manufacturer: 'Generic', model, short: model, modes: {}, heads: 1 };
  for (const [mid, keys] of Object.entries(modes)) {
    const channels = keys.map(k => (Array.isArray(k) ? ch(k[0], k[1]) : ch(k))), set = new Set(channels.map(c => c.key));
    for (const c of channels) { if (/Fine$/.test(c.base)) c.fineOf = c.key.replace('Fine', ''); else if (set.has(c.key + 'Fine')) c.fine = c.key + 'Fine'; }
    out.modes[mid] = { label: mid, channels };
  }
  out.defaultMode = Object.keys(out.modes)[0]; DEFS.set(out.id, out);
}
generic('dimmer', 'Dimmer', { '1CH': ['dimmer'] });
generic('rgb', 'RGB', { '3CH': ['r', 'g', 'b'], '4CH': ['dimmer', 'r', 'g', 'b'] });
generic('rgbw', 'RGBW', { '4CH': ['r', 'g', 'b', 'w'], '6CH': ['dimmer', 'r', 'g', 'b', 'w', 'strobe'] });
generic('rgbaw', 'RGBAW + UV', { '6CH': ['r', 'g', 'b', 'a', 'w', 'uv'], '8CH': ['dimmer', 'strobe', 'r', 'g', 'b', 'a', 'w', 'uv'] });
generic('spot', 'Moving Head Spot', { '14CH': ['pan', 'panFine', 'tilt', 'tiltFine', 'ptSpeed', 'dimmer', 'strobe', 'color', 'gobo', 'prism', 'zoom', 'focus', ['frost', 'Frost'], ['reset', 'Reset']] });
generic('wash', 'Moving Head Wash', { '13CH': ['pan', 'panFine', 'tilt', 'tiltFine', 'ptSpeed', 'dimmer', 'strobe', 'r', 'g', 'b', 'w', 'zoom', ['reset', 'Reset']] });
generic('cmy', 'Moving Head CMY', { '16CH': ['pan', 'panFine', 'tilt', 'tiltFine', 'ptSpeed', 'dimmer', 'strobe', 'cyan', 'magenta', 'yellow', 'color', 'gobo', 'prism', 'zoom', 'focus', ['reset', 'Reset']] });
generic('scanner', 'Scanner', { '6CH': ['pan', 'tilt', 'dimmer', 'strobe', 'color', 'gobo'] });
{ const modes = {}; for (const n of [2, 4, 6, 8, 12, 24, 48]) modes[n + 'CH'] = Array.from({ length: n }, (_, i) => ['dimmer' + (i + 1), 'Channel ' + (i + 1)]); generic('pack', 'Dimmer pack', modes); }

/** load the data profiles (call once at start) */
export async function loadLibrary() {
  try { const j = await (await fetch('fixtures/wincode.json')).json(); for (const f of j.fixtures) DEFS.set(f.id, f); } catch (e) { console.warn('fixture profiles not loaded', e); }
  for (const d of DEFS.values()) for (const m of Object.values(d.modes)) m.index = Object.fromEntries(m.channels.map((c, i) => [c.key, i]));
}
/** a library fixture (description, see libimport.js) as a patchable profile */
export function registerDesc(D) {
  if (DEFS.has(D.id)) return DEFS.get(D.id);
  const d = profileFromDesc(D); for (const m of Object.values(d.modes)) m.index = Object.fromEntries(m.channels.map((c, i) => [c.key, i]));
  DEFS.set(d.id, d); return d;
}
/** a show carries the descriptions of the library fixtures in its patch (show.library): make them known */
export function registerShow(show) { for (const D of Object.values((show && show.library) || {})) try { registerDesc(D); } catch (e) { console.warn('fixture description skipped', D && D.id, e); } }
export const library = () => [...DEFS.values()].sort((a, b) => (a.manufacturer === b.manufacturer ? a.model.localeCompare(b.model) : a.manufacturer === 'Wincode' ? -1 : 1));
export const getDef = id => DEFS.get(id);
export const modeOf = fx => { const d = DEFS.get(fx.def); return d ? d.modes[fx.mode] || d.modes[d.defaultMode] : null; };
export const chanOf = (fx, key) => { const m = modeOf(fx); return m && m.index[key] != null ? m.channels[m.index[key]] : null; };
export const footprint = fx => { const m = modeOf(fx); return m ? m.channels.length : 0; };
/** label of a value from the channel's range table */
export const rangeLabel = (c, v) => { if (!c || !c.ranges.length) return ''; const r = c.ranges.find(x => v >= x[0] && v <= x[1]); return r ? r[2] : ''; };
/** colour mixing a fixture offers: per head, 'rgb' or 'cmy' with the channel keys */
export function mixOf(fx) {
  const m = modeOf(fx); if (!m) return [];
  const heads = new Map();
  for (const c of m.channels) if (['r', 'g', 'b', 'w', 'cyan', 'magenta', 'yellow'].includes(c.base)) { if (!heads.has(c.head)) heads.set(c.head, {}); heads.get(c.head)[c.base] = c.key; }
  return [...heads.values()].filter(k => (k.r && k.g && k.b) || (k.cyan && k.magenta && k.yellow)).map(k => (k.r ? { type: 'rgb', ...k } : { type: 'cmy', ...k }));
}
/** channel values that give this fixture the colour [r, g, b] (0–255) */
export function colourValues(fx, rgb) {
  const out = {};
  for (const k of mixOf(fx)) {
    if (k.type === 'rgb') { out[k.r] = rgb[0]; out[k.g] = rgb[1]; out[k.b] = rgb[2]; if (k.w) out[k.w] = 0; }
    else { out[k.cyan] = 255 - rgb[0]; out[k.magenta] = 255 - rgb[1]; out[k.yellow] = 255 - rgb[2]; }
  }
  return out;
}
/** first free address for a footprint on a universe (0 when it does not fit) */
export function freeAddress(universe, size, ignoreId) {
  const used = new Uint8Array(513);
  for (const f of store.show.fixtures) if (f.universe === universe && f.id !== ignoreId) for (let i = 0; i < footprint(f); i++) used[f.address + i] = 1;
  for (let a = 1; a + size - 1 <= 512; a++) { let ok = true; for (let i = 0; i < size; i++) if (used[a + i]) { ok = false; a += i; break; } if (ok) return a; }
  return 0;
}
